# Spec 130: DepMap genome-wide CRISPR knock-out viability screens (24Q4, Chronos gene effect; < 0 = loss of fitness, about -1 = like a common essential gene) for the TFs of the CROP-seq screen,
# in all mesothelioma lines with a screen (21, including NCI-H2052, MSTO-211H, NCI-H2452, NCI-H28), compared with the proliferation read-outs of the CROP-seq screen in NCI-H2052.
#   A  gene effect, TF x mesothelioma line (our 4 lines first), with the median over all DepMap lines and the dependency probability
#   B  per TF: distribution over the mesothelioma lines, NCI-H2052 and the other 3 bulk lines marked; Wilcoxon mesothelioma vs all other lines
#   C  CROP-seq (H2052): loss of proliferation after KO (cell-cycle score, NTC - KO) vs DepMap gene effect in H2052 and vs the mesothelioma median (10 screen TFs)
#   D  bulk RNA-seq: proliferation score NTC - KO per KO and line (corrected sample set, spec128 inputs) vs the DepMap gene effect of the same gene in the same line
# TFs: the 10 of the screen (8 shared with bulk + MEF2A, MEF2D), plus RUNX2, SNAI2, RUNX1 (bulk only) and TEAD1, TEAD3, TFAP2A (guides designed)
# needs: DepMap 24Q4 CRISPRGeneEffect.csv, CRISPRGeneDependency.csv, Model.csv (DEPMAP_DIR; from figshare article 27993248), spec128_inputs.rds, spec_common.R
# outputs: spec130_depmap_meso_gene_effect.csv, spec130_depmap_TF_summary.csv, fig46_depmap_meso_dependency.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "spec_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 220)
DM <- Sys.getenv("DEPMAP_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/DepMap_24Q4"); fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 0), formatC(p, format = "g", digits = 2)))
SCR <- c(KOS, "MEF2A", "MEF2D"); TF <- c(SCR, "RUNX2", "SNAI2", "RUNX1", "TEAD1", "TEAD3", "TFAP2A"); kcol <- function(k) ifelse(k %in% names(KO_COL), KO_COL[k], "grey30")
rdm <- function(f) { hd <- strsplit(readLines(file.path(DM, f), n = 1), ",")[[1]]; sym <- sub(" \\(.*", "", hd); cols <- c(1, match(TF, sym)); x <- data.table::fread(file.path(DM, f), select = cols, data.table = FALSE); M <- as.matrix(x[, -1]); dimnames(M) <- list(x[[1]], TF); M }
GE <- rdm("CRISPRGeneEffect.csv"); GD <- rdm("CRISPRGeneDependency.csv"); mo <- read.csv(file.path(DM, "Model.csv"), stringsAsFactors = FALSE); mo <- mo[mo$ModelID %in% rownames(GE), ]
meso <- mo[grepl("esotheli", paste(mo$OncotreePrimaryDisease, mo$OncotreeSubtype)), ]; OUR <- c(NCIH2052 = "NCI-H2052", MSTO211H = "MSTO-211H", NCIH2452 = "NCI-H2452", NCIH28 = "NCI-H28"); meso <- meso[order(-(meso$StrippedCellLineName %in% names(OUR)), match(meso$StrippedCellLineName, names(OUR)), meso$StrippedCellLineName), ]
E <- GE[meso$ModelID, ]; rownames(E) <- meso$StrippedCellLineName; Pd <- GD[meso$ModelID, ]; rownames(Pd) <- meso$StrippedCellLineName; oth <- setdiff(rownames(GE), meso$ModelID); cat("DepMap lines with a CRISPR screen:", nrow(GE), "| mesothelioma:", nrow(E), "\n")
write.csv(data.frame(line = rownames(E), subtype = meso$OncotreeSubtype, round(E, 3)), file.path(OUT, "spec130_depmap_meso_gene_effect.csv"), row.names = FALSE)

## screen (H2052): proliferation per KO
srt <- load_screen(); g <- as.character(srt$merged_call); md <- srt@meta.data; set.seed(1)
SC <- do.call(rbind, lapply(SCR, function(k) { a <- md$cc[g == "NTC"]; b <- md$cc[g == k]; data.frame(KO = k, screen_cells = length(b), screen_prolif_drop = mean(a) - mean(b), screen_p = wilcox.test(a, b)$p.value, cycling_NTC = mean(md$Phase[g == "NTC"] != "G1"), cycling_KO = mean(md$Phase[g == k] != "G1")) }))
SUM <- data.frame(KO = TF, in_screen = TF %in% SCR, H2052 = E["NCIH2052", ], MSTO = E["MSTO211H", ], H2452 = E["NCIH2452", ], H28 = E["NCIH28", ], meso_median = apply(E, 2, median, na.rm = TRUE), meso_min = apply(E, 2, min, na.rm = TRUE), meso_n_dependent = colSums(Pd > 0.5, na.rm = TRUE),
                  all_lines_median = apply(GE[oth, ], 2, median, na.rm = TRUE), p_meso_vs_other = sapply(TF, function(k) wilcox.test(E[, k], GE[oth, k])$p.value), H2052_dep_prob = Pd["NCIH2052", ])
SUM <- merge(SUM, SC, by = "KO", all.x = TRUE); SUM <- SUM[match(TF, SUM$KO), ]; write.csv(SUM, file.path(OUT, "spec130_depmap_TF_summary.csv"), row.names = FALSE); print(SUM[, c("KO", "H2052", "MSTO", "H2452", "H28", "meso_median", "meso_min", "meso_n_dependent", "all_lines_median", "p_meso_vs_other", "H2052_dep_prob", "screen_cells", "screen_prolif_drop", "screen_p", "cycling_KO")], digits = 2, row.names = FALSE)
s <- SUM[SUM$in_screen, ]; ct <- function(x, y) { r <- suppressWarnings(cor.test(x, y, method = "spearman", exact = FALSE)); c(r$estimate, r$p.value) }; c1 <- ct(s$screen_prolif_drop, -s$H2052); c2 <- ct(s$screen_prolif_drop, -s$meso_median); c3 <- ct(log10(s$screen_cells), s$H2052)
cat(sprintf("\nscreen proliferation drop vs DepMap loss of fitness (10 screen TFs): H2052 rho %.2f, p %.2g | mesothelioma median rho %.2f, p %.2g | cells recovered in the screen vs H2052 gene effect rho %.2f, p %.2g\n", c1[1], c1[2], c2[1], c2[2], c3[1], c3[2]))
## bulk proliferation per KO x line (corrected sample set)
SA <- readRDS(file.path(OUT, "spec128_inputs.rds"))$SA; BK <- do.call(rbind, lapply(LINES, function(cl) do.call(rbind, lapply(intersect(TF, unique(SA$KO[SA$line == cl])), function(k) data.frame(line = cl, KO = k, bulk_prolif_drop = mean(SA$cc[SA$line == cl & SA$KO == "NTC"]) - mean(SA$cc[SA$line == cl & SA$KO == k]), depmap = E[names(OUR)[OUR == cl], k])))))
c4 <- ct(BK$bulk_prolif_drop, -BK$depmap); cw <- ct(BK$bulk_prolif_drop - ave(BK$bulk_prolif_drop, BK$line), -(BK$depmap - ave(BK$depmap, BK$line))); cat(sprintf("bulk proliferation drop vs DepMap loss of fitness, same gene and line (%d KO x line): rho %.2f, p %.2g | within line: rho %.2f, p %.2g\n", nrow(BK), c4[1], c4[2], cw[1], cw[2]))
cat("DepMap agreement between our 4 lines over the 16 TFs (Spearman):\n"); print(round(cor(t(E[names(OUR), ]), method = "spearman"), 2))

save_fig("fig46_depmap_meso_dependency", 17, 10.6, function() {
  layout(rbind(c(1, 1, 2, 2), c(3, 4, 5, 5)), heights = c(1.1, 1)); par(oma = c(0, 0, 3.6, 0.4), family = "sans"); ttl <- function(a, b) { mtext(a, side = 3, adj = 0, line = 1.5, font = 2, cex = 0.8); mtext(b, side = 3, adj = 0, line = 0.4, cex = 0.56, col = INK2) }
  pal <- colorRampPalette(c("#a8380b", "#f0a58f", "#f7f6f2", "#a9c9ee"))(100); o <- TF[order(SUM$meso_median)]; M <- cbind(t(E[, o]), `all DepMap lines (median)` = SUM$all_lines_median[match(o, SUM$KO)]); nr <- nrow(M); nc <- ncol(M); zl <- c(-1.5, 0.5)
  par(mar = c(6.4, 5.4, 3.4, 1)); image(seq_len(nc), seq_len(nr), t(pmax(pmin(M, zl[2]), zl[1])[nr:1, ]), col = pal, zlim = zl, axes = FALSE, xlab = "", ylab = ""); text(rep(seq_len(nc), each = nr), rep(nr:1, nc), sprintf("%.1f", as.vector(M)), cex = 0.52, col = ifelse(as.vector(M) < -1, "white", "black"))
  axis(1, at = seq_len(nc), labels = colnames(M), las = 2, tick = FALSE, cex.axis = 0.62, font.axis = 1); text(0.35, nr:1, o, adj = 1, xpd = NA, cex = 0.75, font = 2, col = kcol(o)); abline(v = c(4.5, nc - 0.5), lwd = 2, col = "white"); points(rep(-1.1, nr), nr:1, pch = ifelse(o %in% SCR, 16, 1), cex = 0.7, xpd = NA, col = INK2)
  ttl("A  DepMap CRISPR gene effect in the 21 mesothelioma lines", "Chronos score: 0 = no effect, -1 = like a common essential gene; our 4 lines first; filled dot = TF in the CROP-seq screen")
  par(mar = c(4.4, 5.4, 3.4, 5)); plot(NA, xlim = range(E, na.rm = TRUE) + c(-0.05, 0.05), ylim = c(nr + 0.6, 0.4), yaxt = "n", bty = "n", las = 1, xlab = "DepMap gene effect (Chronos)", ylab = "", cex.axis = 0.8); abline(v = c(0, -0.5, -1), lty = c(1, 3, 2), col = c(INK, MUTED, MUTED))
  for (i in seq_along(o)) { v <- E[, o[i]]; boxplot(v, at = i, add = TRUE, horizontal = TRUE, boxwex = 0.55, col = adjustcolor(kcol(o[i]), 0.35), border = INK2, outline = FALSE, axes = FALSE); points(v, i + runif(length(v), -0.15, 0.15), pch = 16, cex = 0.45, col = "grey45")
    points(E[names(OUR)[-1], o[i]], rep(i, 3), pch = c(22, 24, 23), bg = LINE_COL[OUR[-1]], col = INK2, cex = 1.1); points(E["NCIH2052", o[i]], i, pch = 21, bg = LINE_COL[["NCI-H2052"]], col = "black", cex = 1.7, lwd = 1.5)
    r <- SUM[SUM$KO == o[i], ]; text(par("usr")[2] + 0.02, i, sprintf("%d/21 dep.; p %s", r$meso_n_dependent, fp(r$p_meso_vs_other)), adj = 0, xpd = NA, cex = 0.58, font = ifelse(r$p_meso_vs_other < 0.05, 2, 1)) }
  text(par("usr")[1] - 0.03, seq_along(o), o, adj = 1, xpd = NA, cex = 0.75, font = 2, col = kcol(o)); legend("bottomleft", c("NCI-H2052", sub("NCI-|-211H", "", OUR[-1]), "other mesothelioma lines"), pch = c(21, 22, 24, 23, 16), pt.bg = c(LINE_COL[OUR], NA), col = c("black", rep(INK2, 3), "grey45"), pt.cex = c(1.5, 1, 1, 1, 0.6), bty = "n", cex = 0.62)
  ttl("B  spread over the mesothelioma lines", "right: lines with dependency probability > 0.5, and Wilcoxon p mesothelioma vs all other DepMap lines; dashed = -1")
  for (v in c("H2052", "meso_median")) { par(mar = c(4.4, 4.8, 3.4, 1)); plot(s$screen_prolif_drop, s[[v]], pch = 21, bg = kcol(s$KO), col = INK2, cex = 2, bty = "n", las = 1, xlab = "CROP-seq (H2052): proliferation score, NTC - KO", ylab = if (v == "H2052") "DepMap gene effect in NCI-H2052" else "DepMap gene effect, mesothelioma median", cex.axis = 0.8, xlim = range(s$screen_prolif_drop) + c(-0.03, 0.08), ylim = rev(range(s[[v]]) + c(-0.08, 0.08)))
    abline(h = 0, v = 0, lty = 2, col = GRID); text(s$screen_prolif_drop, s[[v]], s$KO, pos = 4, cex = 0.66, font = 2, col = kcol(s$KO), xpd = NA); r <- if (v == "H2052") c1 else c2; ttl(if (v == "H2052") "C  CROP-seq vs DepMap, same line (H2052)" else "    CROP-seq vs DepMap, mesothelioma median", sprintf("10 screen TFs; y axis reversed (up = more loss of fitness); Spearman %.2f, p %s", r[1], fp(r[2]))) }
  par(mar = c(4.4, 4.8, 3.4, 1)); plot(BK$bulk_prolif_drop, BK$depmap, pch = c(21, 22, 24, 23)[match(BK$line, LINES)], bg = kcol(BK$KO), col = INK2, cex = 1.6, bty = "n", las = 1, xlab = "bulk RNA-seq: proliferation score, NTC - KO (same line)", ylab = "DepMap gene effect (same line)", cex.axis = 0.8, ylim = rev(range(BK$depmap) + c(-0.08, 0.08))); abline(h = 0, v = 0, lty = 2, col = GRID)
  legend("topleft", sub("NCI-|-211H", "", LINES), pch = c(21, 22, 24, 23), pt.bg = "grey70", bty = "n", cex = 0.65); legend("bottomright", unique(BK$KO), pch = 21, pt.bg = kcol(unique(BK$KO)), bty = "n", cex = 0.55, ncol = 2); ttl("D  bulk proliferation after KO vs DepMap, per gene and line", sprintf("%d KO x line; Spearman %.2f, p %s; within line %.2f, p %s", nrow(BK), c4[1], fp(c4[2]), cw[1], fp(cw[2])))
  mtext("DepMap genome-wide CRISPR viability screens: the CROP-seq TFs in mesothelioma lines", outer = TRUE, side = 3, adj = 0, line = 2, font = 2, cex = 1.05); mtext("DepMap Public 24Q4, Chronos gene effect; 21 pleural mesothelioma lines with a screen", outer = TRUE, side = 3, adj = 0, line = 0.8, cex = 0.66, col = INK2)
})
